public class Main {static int countAlerts(int[] readings,int k,int threshold){if(readings==null||k<1||k>readings.length)throw new IllegalArgumentException();int sum=0,count=0;for(int i=0;i<k;i++)sum+=readings[i];if(sum>=k*threshold)count++;for(int i=k;i<readings.length;i++){sum+=readings[i]-readings[i-k];if(sum>=k*threshold)count++;}return count;}public static void main(String[]args){System.out.println(countAlerts(new int[]{2,2,2,2,5,5,5,8},3,4));System.out.println("Time: O(n), extra space: O(1)");}}